CREATE TABLE projects (id uuid PRIMARY KEY, name text NOT NULL, target_template jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE specifications (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, sanitized_document jsonb NOT NULL, sanitized_hash text NOT NULL, openapi_version text NOT NULL, api_model jsonb NOT NULL, diagnostics jsonb NOT NULL DEFAULT '[]');
CREATE TABLE credentials (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, slot_name text NOT NULL, version integer NOT NULL CHECK(version>0), ciphertext bytea NOT NULL, nonce bytea NOT NULL CHECK(octet_length(nonce)=12), auth_tag bytea NOT NULL CHECK(octet_length(auth_tag)=16), key_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,slot_name,version));
CREATE TABLE predicates (id uuid NOT NULL, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, version integer NOT NULL CHECK(version>0), canonical_hash text NOT NULL, definition jsonb NOT NULL, source_ref text NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE approvals (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, kind text NOT NULL, subject_hash text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL);
CREATE TABLE resets (id uuid NOT NULL, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, version integer NOT NULL CHECK(version>0), definition jsonb NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE runs (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, status text NOT NULL CHECK(status IN ('ACCEPTED','RUNNING','STOPPING','COMPLETED','STOPPED','INTERRUPTED')), stop_reason text, accepted_at timestamptz NOT NULL DEFAULT now(), deadline_at timestamptz, immutable_snapshot jsonb NOT NULL, counters jsonb NOT NULL, cancel_at timestamptz, model_config jsonb NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX one_active_global_run ON runs((true)) WHERE status IN ('ACCEPTED','RUNNING','STOPPING');
CREATE TABLE journeys (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, phase text NOT NULL, parent_journey_id uuid REFERENCES journeys, definition jsonb NOT NULL, normalized_hash text NOT NULL, ordinal integer NOT NULL);
CREATE TABLE step_records (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, journey_id uuid REFERENCES journeys ON DELETE CASCADE, trial_id uuid NOT NULL, step_name text NOT NULL, phase text NOT NULL, ordinal integer NOT NULL, request_intent_at timestamptz NOT NULL DEFAULT now(), sanitized_request jsonb NOT NULL, sanitized_response jsonb, outcome text NOT NULL DEFAULT 'INTENT', error_reason text, timing jsonb);
CREATE TABLE observations (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, trial_id uuid NOT NULL, step_record_id uuid NOT NULL REFERENCES step_records ON DELETE CASCADE, sanitized_summary jsonb NOT NULL, provenance_mappings jsonb NOT NULL);
CREATE TABLE evidence (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, trial_id uuid NOT NULL, kind text NOT NULL, predicate_ref jsonb, baseline_id uuid REFERENCES evidence ON DELETE CASCADE, step_refs jsonb NOT NULL, evaluation jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(baseline_id IS NULL OR baseline_id<>id));
CREATE TABLE findings (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, predicate_ref jsonb NOT NULL, initial_evidence_id uuid NOT NULL REFERENCES evidence ON DELETE CASCADE, original_journey_id uuid NOT NULL REFERENCES journeys ON DELETE CASCADE, minimized_journey_id uuid REFERENCES journeys ON DELETE CASCADE, current_classification text NOT NULL CHECK(current_classification IN ('SUSPICIOUS','CONFIRMED','INCONCLUSIVE','NON-REPRODUCED')), consistent boolean NOT NULL DEFAULT true, minimization_stop text);
CREATE TABLE finding_transitions (id uuid PRIMARY KEY, finding_id uuid NOT NULL REFERENCES findings ON DELETE CASCADE, prior_classification text, next_classification text NOT NULL, evidence_refs jsonb NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifacts (id uuid PRIMARY KEY, finding_id uuid NOT NULL REFERENCES findings ON DELETE CASCADE, format text NOT NULL, content_hash text NOT NULL, runner_version text NOT NULL, content bytea NOT NULL, generated_at timestamptz NOT NULL DEFAULT now(), verification_status text NOT NULL CHECK(verification_status IN ('UNVERIFIED','VERIFIED')), evidence_refs jsonb NOT NULL);
CREATE INDEX runs_status ON runs(status);
CREATE INDEX journeys_order ON journeys(run_id,ordinal);
CREATE INDEX steps_order ON step_records(run_id,trial_id,ordinal);
CREATE INDEX evidence_trial ON evidence(run_id,trial_id);
CREATE INDEX findings_run ON findings(run_id);
CREATE FUNCTION reject_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable record'; END $$;
CREATE FUNCTION protect_run_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.immutable_snapshot IS DISTINCT FROM OLD.immutable_snapshot OR NEW.id<>OLD.id OR NEW.project_id<>OLD.project_id OR NEW.accepted_at<>OLD.accepted_at OR NEW.deadline_at IS DISTINCT FROM OLD.deadline_at OR NEW.model_config<>OLD.model_config THEN RAISE EXCEPTION 'Immutable run configuration'; END IF; IF OLD.status IN ('COMPLETED','STOPPED','INTERRUPTED') AND NEW.status<>OLD.status THEN RAISE EXCEPTION 'Terminal run'; END IF; RETURN NEW; END $$;
CREATE TRIGGER run_snapshot BEFORE UPDATE ON runs FOR EACH ROW EXECUTE FUNCTION protect_run_snapshot();
CREATE TRIGGER immutable_spec BEFORE UPDATE ON specifications FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_credential BEFORE UPDATE ON credentials FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_predicate BEFORE UPDATE ON predicates FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_approval BEFORE UPDATE ON approvals FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_reset BEFORE UPDATE ON resets FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_journey BEFORE UPDATE ON journeys FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_observation BEFORE UPDATE ON observations FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_evidence BEFORE UPDATE ON evidence FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE TRIGGER immutable_transition BEFORE UPDATE ON finding_transitions FOR EACH ROW EXECUTE FUNCTION reject_update();
CREATE FUNCTION protect_intent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.outcome<>'INTENT' OR NEW.id<>OLD.id OR NEW.run_id<>OLD.run_id OR NEW.trial_id<>OLD.trial_id OR NEW.step_name<>OLD.step_name OR NEW.ordinal<>OLD.ordinal OR NEW.journey_id IS DISTINCT FROM OLD.journey_id OR NEW.phase<>OLD.phase OR NEW.sanitized_request<>OLD.sanitized_request OR NEW.request_intent_at<>OLD.request_intent_at THEN RAISE EXCEPTION 'Immutable dispatch intent'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_intent BEFORE UPDATE ON step_records FOR EACH ROW EXECUTE FUNCTION protect_intent();
